      90% {\n                opacity: 1;\n            }\n            100% {\n                transform: translateY(-100px) rotate(720deg);\n                opacity: 0;\n            }\n        }\n\n        /* Main Container */\n        .container {\n            position: relative;\n            z-index: 1;\n            max-width: 720px;\n            margin: 0 auto;\n            padding: 40px 20px;\n            min-height: 100vh;\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n        }\n\n        /* Header */\n        .header {\n            text-align: center;\n            margin-bottom: 40px;\n            animation: fadeInDown 0.8s ease;\n        }\n\n        @keyframes fadeInDown {\n            from {\n                opacity: 0;\n                transform: translateY(-30px);\n            }\n            to {\n                opacity: 1;\n                transform: translateY(0);\n            }\n        }\n\n        .logo {\n            font-size: 2.5rem;\n            font-weight: 700;\n            background: linear-gradient(135deg, #02a982, #00d4aa, #7efcdb);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            background-clip: text;\n            margin-bottom: 8px;\n            letter-spacing: 2px;\n        }\n\n        .subtitle {\n            font-size: 1rem;\n            color: #888;\n            margin-top: 12px;\n        }\n\n        .subtitle span {\n            color: #02a982;\n            font-weight: 500;\n        }\n\n        /* Poem Section */\n        .poem {\n            text-align: center;\n            margin-bottom: 32px;\n            padding: 20px 30px;\n            background: rgba(2, 169, 130, 0.05);\n            border: 1px solid rgba(2, 169, 130, 0.15);\n            border-radius: 16px;\n            animation: fadeIn 1s ease 0.3s both;\n        }\n\n        @keyframes fadeIn {\n            from { opacity: 0; transform: translateY(20px); }\n            to { opacity: 1; transform: translateY(0); }\n        }\n\n        .poem p {\n            font-size: 1.1rem;\n            color: #b0b0b0;\n            line-height: 2;\n            font-style: italic;\n        }\n\n        .poem .highlight {\n            color: #02a982;\n            font-weight: 600;\n            font-style: normal;\n        }\n\n        /* Link Cards */\n        .cards {\n            width: 100%;\n            display: flex;\n            flex-direction: column;\n            gap: 16px;\n            margin-bottom: 32px;\n        }\n\n        .card {\n            background: rgba(255, 255, 255, 0.03);\n            border: 1px solid rgba(255, 255, 255, 0.08);\n            border-radius: 16px;\n            padding: 24px;\n            transition: all 0.3s ease;\n            animation: fadeIn 0.6s ease both;\n        }\n\n        .card:nth-child(1) { animation-delay: 0.4s; }\n        .card:nth-child(2) { animation-delay: 0.5s; }\n        .card:nth-child(3) { animation-delay: 0.6s; }\n        .card:nth-child(4) { animation-delay: 0.7s; }\n        .card:nth-child(5) { animation-delay: 0.8s; }\n\n        .card:hover {\n            background: rgba(255, 255, 255, 0.06);\n            border-color: rgba(2, 169, 130, 0.3);\n            transform: translateY(-2px);\n            box-shadow: 0 8px 32px rgba(2, 169, 130, 0.1);\n        }\n\n        .card-header {\n            display: flex;\n            align-items: center;\n            gap: 10px;\n            margin-bottom: 16px;\n        }\n\n        .card-badge {\n            display: inline-flex;\n            align-items: center;\n            gap: 6px;\n            padding: 4px 12px;\n            border-radius: 20px;\n            font-size: 0.75rem;\n            font-weight: 600;\n            letter-spacing: 0.5px;\n        }\n\n        .badge-official {\n            background: rgba(2, 169, 130, 0.15);\n            color: #02a982;\n            border: 1px solid rgba(2, 169, 130, 0.3);\n        }\n\n        .badge-backup {\n            background: rgba(59, 130, 246, 0.15);\n            color: #60a5fa;\n            border: 1px solid rgba(59, 130, 246, 0.3);\n        }\n\n        .badge-blocked {\n            background: rgba(239, 68, 68, 0.15);\n            color: #f87171;\n            border: 1px solid rgba(239, 68, 68, 0.3);\n        }\n\n        .badge-new {\n            background: rgba(168, 85, 247, 0.15);\n            color: #c084fc;\n            border: 1px solid rgba(168, 85, 247, 0.3);\n        }\n\n        .badge-mobile {\n            background: rgba(245, 158, 11, 0.15);\n            color: #fbbf24;\n            border: 1px solid rgba(245, 158, 11, 0.3);\n        }\n\n        .card-title {\n            font-size: 1rem;\n            font-weight: 600;\n            color: #e0e0e0;\n        }\n\n        .link-item {\n            display: flex;\n            align-items: center;\n            justify-content: space-between;\n            padding: 12px 16px;\n            background: rgba(0, 0, 0, 0.2);\n            border-radius: 10px;\n            margin-bottom: 8px;\n            transition: all 0.2s ease;\n        }\n\n        .link-item:last-child {\n            margin-bottom: 0;\n        }\n\n        .link-item:hover {\n            background: rgba(2, 169, 130, 0.08);\n        }\n\n        .link-url {\n            font-size: 0.9rem;\n            color: #02a982;\n            text-decoration: none;\n            font-family: 'Courier New', monospace;\n            transition: color 0.2s;\n        }\n\n        .link-url:hover {\n            color: #7efcdb;\n        }\n\n        .link-btn {\n            display: inline-flex;\n            align-items: center;\n            gap: 6px;\n            padding: 6px 16px;\n            background: linear-gradient(135deg, #02a982, #00c896);\n            color: #fff;\n            border: none;\n            border-radius: 8px;\n            font-size: 0.8rem;\n            font-weight: 500;\n            cursor: pointer;\n            text-decoration: none;\n            transition: all 0.2s ease;\n            white-space: nowrap;\n        }\n\n        .link-btn:hover {\n            transform: scale(1.05);\n            box-shadow: 0 4px 16px rgba(2, 169, 130, 0.4);\n        }\n\n        .link-btn svg {\n            width: 14px;\n            height: 14px;\n        }\n\n        /* QR Code Section */\n        .qr-section {\n            text-align: center;\n            animation: fadeIn 0.6s ease 0.9s both;\n        }\n\n        .qr-section .card {\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n        }\n\n        .qr-wrapper {\n            padding: 16px;\n            background: #fff;\n            border-radius: 12px;\n            margin: 12px 0;\n            display: inline-block;\n        }\n\n        .qr-wrapper canvas,\n        .qr-wrapper img {\n            display: block;\n        }\n\n        .qr-hint {\n            font-size: 0.85rem;\n            color: #888;\n            margin-top: 8px;\n        }\n\n        .qr-hint strong {\n            color: #f87171;\n        }\n\n        /* Notice Section */\n        .notice {\n            width: 100%;\n            margin-top: 24px;\n            padding: 20px 24px;\n            background: rgba(239, 68, 68, 0.05);\n            border: 1px solid rgba(239, 68, 68, 0.15);\n            border-radius: 16px;\n            animation: fadeIn 0.6s ease 1s both;\n        }\n\n        .notice-title {\n            display: flex;\n            align-items: center;\n            gap: 8px;\n            font-size: 0.9rem;\n            font-weight: 600;\n            color: #f87171;\n            margin-bottom: 12px;\n        }\n\n        .notice-title svg {\n            width: 18px;\n            height: 18px;\n        }\n\n        .notice p {\n            font-size: 0.85rem;\n            color: #999;\n            line-height: 1.8;\n        }\n\n        .notice a {\n            color: #02a982;\n            text-decoration: none;\n            border-bottom: 1px dashed rgba(2, 169, 130, 0.4);\n            transition: all 0.2s;\n        }\n\n        .notice a:hover {\n            color: #7efcdb;\n            border-bottom-color: #7efcdb;\n        }\n\n        /* Friend Links Section */\n        .friend-links {\n            width: 100%;\n            margin-top: 32px;\n            padding: 24px;\n            background: rgba(255, 255, 255, 0.02);\n            border: 1px solid rgba(255, 255, 255, 0.06);\n            border-radius: 16px;\n            animation: fadeIn 0.6s ease 1.1s both;\n        }\n\n        .friend-links-header {\n            display: flex;\n            align-items: center;\n            gap: 10px;\n            margin-bottom: 20px;\n            padding-bottom: 16px;\n            border-bottom: 1px solid rgba(255, 255, 255, 0.08);\n        }\n\n        .friend-links-icon {\n            width: 32px;\n            height: 32px;\n            background: linear-gradient(135deg, rgba(2, 169, 130, 0.2), rgba(0, 212, 170, 0.2));\n            border-radius: 8px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n        }\n\n        .friend-links-icon svg {\n            width: 18px;\n            height: 18px;\n            color: #02a982;\n        }\n\n        .friend-links-title {\n            font-size: 1rem;\n            font-weight: 600;\n            color: #e0e0e0;\n        }\n\n        .friend-links-subtitle {\n            font-size: 0.75rem;\n            color: #666;\n            margin-left: auto;\n        }\n\n        .friend-links-grid {\n            display: grid;\n            grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));\n            gap: 12px;\n        }\n\n        .friend-link-item {\n            display: flex;\n            align-items: center;\n            gap: 10px;\n            padding: 12px 14px;\n            background: rgba(0, 0, 0, 0.15);\n            border: 1px solid rgba(255, 255, 255, 0.05);\n            border-radius: 10px;\n            text-decoration: none;\n            transition: all 0.2s ease;\n        }\n\n        .friend-link-item:hover {\n            background: rgba(2, 169, 130, 0.08);\n            border-color: rgba(2, 169, 130, 0.2);\n            transform: translateY(-2px);\n        }\n\n        .friend-link-favicon {\n            width: 20px;\n            height: 20px;\n            border-radius: 4px;\n            background: rgba(2, 169, 130, 0.1);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            flex-shrink: 0;\n        }\n\n        .friend-link-favicon svg {\n            width: 12px;\n            height: 12px;\n            color: #02a982;\n        }\n\n        .friend-link-name {\n            font-size: 0.85rem;\n            color: #b0b0b0;\n            white-space: nowrap;\n            overflow: hidden;\n            text-overflow: ellipsis;\n            transition: color 0.2s;\n        }\n\n        .friend-link-item:hover .friend-link-name {\n            color: #02a982;\n        }\n\n        /* Footer */\n        .footer {\n            margin-top: 40px;\n            text-align: center;\n            font-size: 0.8rem;\n            color: #555;\n            animation: fadeIn 0.6s ease 1.2s both;\n        }\n\n        /* Responsive */\n        @media (max-width: 480px) {\n            .container {\n                padding: 24px 16px;\n            }\n\n            .logo {\n                font-size: 1.8rem;\n            }\n\n            .card {\n                padding: 18px;\n            }\n\n            .link-item {\n                flex-direction: column;\n                gap: 10px;\n                align-items: flex-start;\n            }\n\n            .link-btn {\n                align-self: stretch;\n                justify-content: center;\n            }\n\n            .friend-links-grid {\n                grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));\n                gap: 10px;\n            }\n\n            .friend-link-item {\n                padding: 10px 12px;\n            }\n\n            .friend-link-name {\n                font-size: 0.8rem;\n            }\n        }\n\n        /* Glow effect */\n        .glow-orb {\n            position: fixed;\n            border-radius: 50%;\n            filter: blur(80px);\n            pointer-events: none;\n            z-index: 0;\n        }\n\n        .glow-orb-1 {\n            width: 300px;\n            height: 300px;\n            background: rgba(2, 169, 130, 0.08);\n            top: 10%;\n            left: -5%;\n            animation: orbFloat 8s ease-in-out infinite;\n        }\n\n        .glow-orb-2 {\n            width: 250px;\n            height: 250px;\n            background: rgba(59, 130, 246, 0.06);\n            bottom: 10%;\n            right: -5%;\n            animation: orbFloat 10s ease-in-out infinite reverse;\n        }\n\n        @keyframes orbFloat {\n            0%, 100% { transform: translate(0, 0); }\n            50% { transform: translate(30px, -30px); }\n        }\n\n        /* Status indicator */\n        .status-dot {\n            width: 8px;\n            height: 8px;\n            border-radius: 50%;\n            display: inline-block;\n            animation: pulse 2s ease-in-out infinite;\n        }\n\n        .status-active {\n            background: #02a982;\n            box-shadow: 0 0 8px rgba(2, 169, 130, 0.6);\n        }\n\n        .status-blocked {\n            background: #f87171;\n            box-shadow: 0 0 8px rgba(239, 68, 68, 0.6);\n        }\n\n        @keyframes pulse {\n            0%, 100% { opacity: 1; }\n            50% { opacity: 0.5; }\n        }\n\n        .date-tag {\n            font-size: 0.7rem;\n            color: #666;\n            margin-left: auto;\n        }\n    </style>\n</head>\n<body>\n    <!-- Background Effects -->\n    <div class=\"glow-orb glow-orb-1\"></div>\n    <div class=\"glow-orb glow-orb-2\